import React from "react";

/// React router dom
import { BrowserRouter as Router, Switch, Route } from "react-router-dom";

/// Css
import "./index.css";
import "./chart.css";

/// Layout
import Nav from "./layouts/nav";
import Footer from "./layouts/Footer";
import Login from "./pages/Login";
import LockScreen from "./pages/LockScreen";
import Error404 from "./pages/Error404";
import Widget from "./pages/Widget";
import WorkoutStatistic from "./components/Dashboard/WorkoutStatistic";
import AppProfile from "./components/AppsMenu/AppProfile/AppProfile";
import BootstrapTable from "./components/table/BootstrapTable";
import Element from "./components/Forms/Element/Element";

const Markup = () => {
  const routes = [
    /// Deshborad
    { url: "", component: WorkoutStatistic },
    { url: "summary", component: WorkoutStatistic },
    /// Apps
    { url: "app-profile", component: AppProfile },
    /// table
    { url: "table-bootstrap-basic", component: BootstrapTable },
    /// Form
    { url: "form-element", component: Element },
    /// pages
    { url: "widget-basic", component: Widget },
  ];

  const loggedOutRoutes = [
    { url: "lock-screen", component: LockScreen },
    { url: "login", component: Login },
    { url: undefined, component: Error404 },
  ];

  return (
    <Router basename="/">
      <Switch>
        <React.Fragment>
          {loggedOutRoutes.map((data, i) => (
            <Route
              key={i}
              exact
              path={`/${data.url}`}
              component={<>{data.component}</>}
            />
          ))}
        </React.Fragment>
      </Switch>
      <Switch>
        <React.Fragment>
          {routes.map((data, i) => (
            <Route
              key={i}
              exact
              path={`/${data.url}`}
                component={(e) => 
                 <React.JSX.Element>
                  <div id="main-wrapper" className="show">
                    <Nav />
                    <div className="content-body">
                      <div className="container-fluid">{data.component}</div>
                    </div>
                    <Footer />
                  </div></React.JSX.Element>
              }
            />
          ))}
        </React.Fragment>
      </Switch>
    </Router>
  );
};

export default Markup;
